import * as React from 'react';
import { cn } from '@/lib/utils';

export type ContactItem = {
  label: string;
  value: string;
  href?: string;
  icon?: React.ReactNode;
};

export type ContactStripProps = React.HTMLAttributes<HTMLUListElement> & {
  /** Contact rows to display. */
  items: ContactItem[];
  /** Desktop column count (2-3). Default 2. */
  columns?: 2 | 3;
  /** Content alignment. Default 'left'. */
  align?: 'left' | 'center';
  /** Custom link element for routers. */
  linkComponent?: React.ElementType;
};

const columnClasses: Record<NonNullable<ContactStripProps['columns']>, string> = {
  2: 'sm:grid-cols-2',
  3: 'sm:grid-cols-3',
};

/**
 * Compact contact details strip for the end of a marketing page. Each row
 * pairs a short label with a phone, email, address or link.
 */
export const ContactStrip = React.forwardRef<HTMLUListElement, ContactStripProps>(function ContactStrip(
  { items, columns = 2, align = 'left', linkComponent, className, ...props },
  ref
) {
  const Link = linkComponent ?? 'a';

  return (
    <ul ref={ref} className={cn('grid gap-6', columnClasses[columns], className)} {...props}>
      {items.map((item) => (
        <li key={item.label} className={cn('flex min-w-0 items-start gap-3', align === 'center' && 'justify-center text-center')}>
          {item.icon && (
            <span className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-primary/10 text-primary [&_svg]:size-4">
              {item.icon}
            </span>
          )}
          <div className="min-w-0">
            <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">{item.label}</p>
            {item.href ? (
              <Link href={item.href} className="mt-0.5 block break-words text-sm font-medium text-primary underline-offset-4 hover:underline">
                {item.value}
              </Link>
            ) : (
              <p className="mt-0.5 break-words text-sm font-medium">{item.value}</p>
            )}
          </div>
        </li>
      ))}
    </ul>
  );
});

{
  "id": "contact-strip",
  "name": "ContactStrip",
  "tier": "molecule",
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.7.0",
  "sourceDir": "contact-strip",
  "exportName": "ContactStrip",
  "description": "Compact labelled contact rows with optional icons and links.",
  "designIntent": "Marketing footers and contact sections repeat phone, email and address rows. ContactStrip keeps the label/value pairing consistent and gives phone and email links the right destination.",
  "props": [
    {
      "name": "items",
      "type": "ContactItem[]",
      "required": true,
      "description": "Contact rows: label, value, optional href and icon."
    },
    {
      "name": "columns",
      "type": "2 | 3",
      "required": false,
      "defaultValue": "2",
      "description": "Desktop column count."
    },
    {
      "name": "align",
      "type": "'left' | 'center'",
      "required": false,
      "defaultValue": "left",
      "enum": [
        "left",
        "center"
      ],
      "description": "Row alignment."
    },
    {
      "name": "linkComponent",
      "type": "React.ElementType",
      "required": false,
      "description": "Custom link element for routers."
    }
  ],
  "examples": [
    {
      "title": "Contact details",
      "code": "<ContactStrip\n  items={[\n    { label: 'Call', value: '1.800.860.4519', href: 'tel:18008604519' },\n    { label: 'Email', value: 'info@axial.net', href: 'mailto:info@axial.net' },\n  ]}\n/>",
      "description": "Phone and email rows with links."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't use a bare URL as the label",
      "explanation": "The label should name the channel (Call, Email, Address), not repeat the value.",
      "example": "// Avoid\n{ label: 'info@axial.net', value: 'info@axial.net' }"
    }
  ],
  "accessibility": [
    {
      "feature": "List semantics",
      "implementation": "Renders ul/li with a label and a value per row",
      "userRequirements": "Keep labels short and distinct"
    },
    {
      "feature": "Contact links",
      "implementation": "Phone uses tel: and email uses mailto: when provided",
      "userRequirements": "Provide the correct href scheme"
    }
  ],
  "compositionRules": [
    {
      "component": "SiteFooter",
      "relationship": "Place ContactStrip in the footer contact column",
      "example": "<SiteFooter columns={columns} />"
    }
  ],
  "relatedComponents": [
    "SiteFooter",
    "Link",
    "Text"
  ]
}
